#!/usr/bin/env python3
"""Standalone validated finite-continuation engine for the third chart v0.9.27."""
from __future__ import annotations

import argparse
import base64
import gzip
import hashlib
import importlib.util
import json
import platform
import sys
import time
from decimal import Decimal, ROUND_FLOOR, getcontext
from pathlib import Path
from typing import Any

VERSION = "0.9.27"
TITLE = "GEOMETRIC-FLOW VALIDATED THIRD-CHART FINITE CONTINUATION ENGINE"
EMBEDDED_V0926_SHA256 = "be24417a092ae0cd21d9394bd2ac2a36edb696b1ec56bdc516e0a3bfc8f65f15"
EMBEDDED_V0926_GZIP_B64 = ""
getcontext().prec = 90


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1 << 20), b""):
            h.update(block)
    return h.hexdigest()


def sha256_json(value: Any) -> str:
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()).hexdigest()


def atomic_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(value, indent=2, sort_keys=True, allow_nan=False) + "\n", encoding="utf-8")
    tmp.replace(path)


def materialize(path: Path) -> Path:
    raw = gzip.decompress(base64.b64decode(EMBEDDED_V0926_GZIP_B64))
    if hashlib.sha256(raw).hexdigest() != EMBEDDED_V0926_SHA256:
        raise RuntimeError("embedded v0.9.26 source hash mismatch")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(raw)
    return path.resolve()


def load_module(path: Path):
    spec = importlib.util.spec_from_file_location("embedded_geometric_flow_v0926", path)
    if spec is None or spec.loader is None:
        raise RuntimeError("cannot load embedded v0.9.26")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def dec(value: Any, label: str) -> Decimal:
    result = Decimal(str(value))
    if not result.is_finite():
        raise ValueError(f"{label} is not finite")
    return result


def max_abs_box(box: Any) -> Decimal:
    if not isinstance(box, dict):
        raise ValueError("transformed endpoint box missing")
    lo, hi = box.get("lower"), box.get("upper")
    if not isinstance(lo, list) or not isinstance(hi, list) or len(lo) != 6 or len(hi) != 6:
        raise ValueError("transformed endpoint box must be six-dimensional")
    values = []
    for index, (a, b) in enumerate(zip(lo, hi)):
        da, db = dec(a, f"lower[{index}]"), dec(b, f"upper[{index}]")
        if da > db:
            raise ValueError("endpoint interval is reversed")
        values.append(max(abs(da), abs(db)))
    return max(values)


def parse() -> tuple[argparse.Namespace, list[str]]:
    parser = argparse.ArgumentParser()
    parser.add_argument("--outdir", default="response_fibre_third_chart_finite_v0_9_27_results")
    parser.add_argument("--steps", type=int, default=None, help="requested steps; default certifies through uniform-domain exhaustion")
    parser.add_argument("--max-search-steps", type=int, default=100000)
    return parser.parse_known_args()


def run(args: argparse.Namespace) -> dict[str, Any]:
    started = time.time()
    if args.steps is not None and args.steps < 1:
        raise ValueError("--steps must be positive")
    if args.max_search_steps < 2:
        raise ValueError("--max-search-steps must be at least two")
    out = Path(args.outdir).resolve()
    out.mkdir(parents=True, exist_ok=True)
    embedded = materialize(out / "embedded_sources" / "response_fibre_third_picard_v0_9_26_standalone.py")
    v0926 = load_module(embedded)
    inner_out = out / "v0926_formal_base"
    base = v0926.run(argparse.Namespace(outdir=str(inner_out), root_radius="2e-18", new_domain_radius="1e-11"))
    if base.get("all_scientific_gates_pass") is not True or base.get("third_local_picard_chart_certified") is not True:
        raise RuntimeError("embedded v0.9.26 formal base did not pass")

    frame_path = inner_out / "v0925_third_chart_chain" / "third_frame_arb_certificate.json"
    picard_path = Path(base["repository_native_picard_certificate"])
    frame = json.loads(frame_path.read_text(encoding="utf-8"))
    picard = json.loads(picard_path.read_text(encoding="utf-8"))
    initial = max_abs_box(frame.get("transformed_endpoint_box"))
    domain = min(abs(dec(x, "domain lower")) for x in frame["new_start_domain_box"]["lower"])
    h = dec(picard.get("certified_time_step"), "time step")
    M = dec(picard.get("intrinsic_field_sup_norm_upper"), "field sup")
    L = dec(picard.get("cauchy_lipschitz_upper"), "Lipschitz bound")
    descent = dec(picard.get("intrinsic_projected_gradient_norm_lower"), "descent lower")
    if not (initial < domain and h > 0 and M >= 0 and L >= 0 and descent > 0):
        raise RuntimeError("invalid frozen continuation bounds")
    growth = (L * h).exp()
    increment = h * M

    records: list[dict[str, Any]] = []
    radius = initial
    last_safe = 0
    first_failing = None
    for step in range(1, args.max_search_steps + 1):
        next_radius = growth * radius + increment
        safe = next_radius < domain
        records.append({
            "step": step,
            "start_radius_upper": str(radius),
            "endpoint_radius_upper": str(next_radius),
            "strictly_inside_start_domain": safe,
        })
        if safe:
            radius = next_radius
            last_safe = step
        else:
            first_failing = step
            break
    if first_failing is None:
        raise RuntimeError("uniform-domain exhaustion not located within --max-search-steps")
    maximum = last_safe
    requested = maximum if args.steps is None else args.steps
    requested_within = 1 <= requested <= maximum
    requested_radius = initial
    for _ in range(requested):
        requested_radius = growth * requested_radius + increment
    all_inclusions = requested_within and all(r["strictly_inside_start_domain"] for r in records[:requested])

    certificate = {
        "schema": "geometric-flow/third-chart-finite-continuation/v0.9.27",
        "generator_version": VERSION,
        "embedded_v0926_sha256": EMBEDDED_V0926_SHA256,
        "v0926_summary_sha256": sha256_file(inner_out / "run_summary.json"),
        "third_frame_certificate_sha256": sha256_file(frame_path),
        "third_picard_certificate_sha256": sha256_file(picard_path),
        "recurrence": "r_(n+1) <= exp(L*h)*r_n + h*M",
        "initial_overlap_linf_radius": str(initial),
        "inner_domain_radius": str(domain),
        "field_sup_norm_upper": str(M),
        "induced_lipschitz_upper": str(L),
        "time_step": str(h),
        "growth_factor_upper": str(growth),
        "field_increment_upper": str(increment),
        "maximum_certified_steps": maximum,
        "first_failing_step": first_failing,
        "last_safe_radius": str(radius),
        "first_failing_radius": records[-1]["endpoint_radius_upper"],
        "step_records": records,
        "uniform_strict_L6_descent_lower": str(descent),
        "all_endpoint_inclusions_through_maximum_strict": all(r["strictly_inside_start_domain"] for r in records[:maximum]),
        "claim_boundary": "finite continuation inside the certified third local chart only; no complete-child, atlas-wide, or global-flow theorem",
    }
    cert_path = out / "third_chart_finite_continuation_certificate.json"
    atomic_json(cert_path, certificate)
    gates = {
        "embedded_v0926_hash_exact": sha256_file(embedded) == EMBEDDED_V0926_SHA256,
        "v0926_third_local_picard_chart": base.get("third_local_picard_chart_certified") is True,
        "initial_overlap_box_strictly_inside_domain": initial < domain,
        "positive_frozen_time_step": h > 0,
        "finite_nonnegative_field_and_lipschitz_bounds": M >= 0 and L >= 0,
        "requested_steps_within_uniform_domain": requested_within,
        "all_requested_endpoint_inclusions_strict": all_inclusions,
        "uniform_strict_L6_descent": descent > 0,
        "first_uniform_domain_failure_located": first_failing == maximum + 1,
    }
    passed = all(gates.values())
    result = {
        "title": TITLE,
        "version": VERSION,
        "scientific_status": "VALIDATED_THIRD_CHART_FINITE_CONTINUATION_CERTIFIED" if passed else "THIRD_CHART_FINITE_CONTINUATION_INCONCLUSIVE_FAIL_CLOSED",
        "requested_steps": requested,
        "maximum_steps_under_uniform_bounds": maximum,
        "first_failing_step": first_failing,
        "total_certified_time": str(h * Decimal(requested)),
        "initial_overlap_linf_radius": str(initial),
        "final_requested_radius": str(requested_radius),
        "last_safe_radius_at_exhaustion": str(radius),
        "first_failing_radius": records[-1]["endpoint_radius_upper"],
        "inner_domain_radius": str(domain),
        "minimum_cumulative_L6_drop": str(descent * h * Decimal(requested)),
        "error_propagation": {
            "recurrence": certificate["recurrence"],
            "growth_factor_upper": str(growth),
            "field_increment_upper": str(increment),
        },
        "gates": gates,
        "all_scientific_gates_pass": passed,
        "third_local_picard_chart_certified": True,
        "third_chart_finite_continuation_certified": passed,
        "uniform_domain_exhaustion_located": first_failing is not None,
        "complete_child_certified": False,
        "ten_chart_continuation_certified": False,
        "global_flow_claimed": False,
        "certificate": str(cert_path),
        "certificate_sha256": sha256_file(cert_path),
        "next_required_step": "construct a fourth same-chart recenter target from a signed six-component terminal endpoint box; scalar exhaustion is not a trajectory-centre certificate",
        "claim_boundary": certificate["claim_boundary"],
        "elapsed_seconds": time.time() - started,
        "environment": {"python": platform.python_version(), "platform": platform.platform()},
    }
    result["report_sha256_before_self_field"] = sha256_json(result)
    atomic_json(out / "run_summary.json", result)
    return result


def main() -> int:
    args, ignored = parse()
    if ignored:
        print(f"[notice] ignored notebook/kernel arguments: {ignored}")
    try:
        result = run(args)
        print("=" * 112)
        print(f"{TITLE} v{VERSION}")
        print("=" * 112)
        print(json.dumps(result, indent=2, allow_nan=False))
        return 0 if result["all_scientific_gates_pass"] else 2
    except Exception as exc:
        print(json.dumps({"scientific_status": "V0927_FAILED_CLOSED", "error_type": type(exc).__name__, "error": str(exc)}, indent=2))
        return 2


if __name__ == "__main__":
    code = main()
    if "ipykernel" not in sys.modules and "google.colab" not in sys.modules:
        raise SystemExit(code)
